# ---------------------------------------------------------------- Graeco-Latin
L("rancangan-graeco-latin",
  [(r"Membangun bujur sangkar ortogonal untuk t prima",
    [r"Untuk \(t\) bilangan prima, bujur sangkar Latin yang saling ortogonal dapat dibuat dengan aritmetika modulo. Isi sel pada baris \(i\) dan kolom \(j\) (dimulai dari 0) adalah \(i+aj\) modulo \(t\), dengan \(a=1,2,\dots,t-1\). Setiap nilai \(a\) memberi satu bujur sangkar Latin, dan setiap dua bujur sangkar dengan \(a\) berbeda saling ortogonal.",
     r"Jadi untuk \(t\) prima (dan juga pangkat prima, dengan aritmetika lapangan Galois) tersedia \(t-1\) bujur sangkar yang saling ortogonal, jumlah maksimum yang mungkin. Bujur sangkar Graeco-Latin cukup memakai dua di antaranya."],
    [r"L^{(a)}_{ij}=(i+a\,j)\bmod t,\qquad a=1,\dots,t-1;\qquad \text{maksimum }t-1\ \text{bujur sangkar saling ortogonal}"]),
   (r"Model dan analisis",
    [r"Model memuat empat faktor aditif: baris, kolom, huruf Latin, dan huruf Yunani. Salah satu huruf biasanya adalah perlakuan yang diteliti, sedangkan tiga lainnya adalah faktor pengganggu, atau dua di antaranya perlakuan bila tujuan memang menguji dua faktor tanpa interaksi.",
     r"Setiap faktor punya \(t-1\) db, sehingga galat hanya \((t-1)(t-3)\). Untuk \(t=4\) galat hanya 3 db dan uji sangat lemah; ulangi bujur sangkar atau gunakan \(t\ge5\)."],
    [r"y_{ijkl}=\mu+\rho_i+\gamma_j+\tau_k+\omega_l+\varepsilon_{ijkl},\qquad db_{\text{galat}}=(t-1)(t-3)"]),
   (r"Rancangan hyper-Graeco-Latin",
    [r"Bila tersedia tiga atau lebih bujur sangkar yang saling ortogonal, semuanya dapat ditumpangkan sekaligus untuk mengendalikan lebih banyak faktor. Untuk \(t\) prima ada \(t-1\) bujur sangkar, sehingga secara teori dapat dikendalikan sampai \(t+1\) faktor (termasuk baris dan kolom). Pada titik itu semua db habis untuk faktor dan tidak ada db galat; dalam praktik sisakan setidaknya beberapa db untuk galat."],
    []),
   (r"Kapan rancangan ini dipakai",
    [r"Graeco-Latin cocok untuk percobaan industri atau laboratorium dengan beberapa sumber gangguan yang dapat diidentifikasi, misalnya bahan baku (baris), operator (kolom), mesin (huruf Yunani), dan metode (huruf Latin). Pada percobaan lapangan jarang dipakai karena asumsi tanpa interaksi antar empat faktor sulit dipenuhi dan db galat sedikit."],
    [])],
  [(r"Mengapa bujur sangkar Graeco-Latin 6×6 tidak dapat dibuat?",
    r"Euler menduga dan Tarry (1900) membuktikan bahwa tidak ada pasangan bujur sangkar Latin 6×6 yang saling ortogonal. Untuk semua \(t\ge3\) lainnya pasangan itu ada."),
   (r"Berapa db galat Graeco-Latin 5×5 dan 7×7?",
    r"5×5: \((4)(2)=8\). 7×7: \((6)(4)=24\)."),
   (r"Dengan rumus \((i+aj)\bmod 5\), tuliskan baris \(i=2\) untuk \(a=1\) dan \(a=2\) (kolom \(j=0\) sampai 4).",
    r"\(a=1\): 2, 3, 4, 0, 1. \(a=2\): 2, 4, 1, 3, 0."),
   (r"Berapa bujur sangkar saling ortogonal maksimum untuk \(t=7\), dan berapa faktor yang secara teori dapat dikendalikan?",
    r"\(t-1=6\) bujur sangkar, sehingga baris, kolom, dan 6 huruf: 8 faktor. Seluruh \(49-1=48\) db habis (8 × 6), tanpa db galat."),
   (r"Peneliti ingin menguji 5 metode dengan pengganggu bahan baku, operator, dan mesin, masing-masing 5 taraf. Rancangan apa yang sesuai dan berapa banyak percobaan?",
    r"Graeco-Latin 5×5: bahan baku sebagai baris, operator sebagai kolom, mesin sebagai huruf Yunani, metode sebagai huruf Latin. Banyak percobaan 25 dengan 8 db galat.")],
  [R_MONT, R_CC, R_HK, R_BHH],
  contoh2=dict(judul="Contoh kedua: membangun Graeco-Latin 5×5",
               soal="Bangun bujur sangkar Graeco-Latin 5×5 dengan aritmetika modulo 5: huruf Latin dari a = 1 dan huruf Yunani dari a = 2. Angka 0–4 dipetakan ke A–E dan α–ε.",
               data=[["Baris", "K0", "K1", "K2", "K3", "K4"], ["0", "Aα", "Bγ", "Cε", "Dβ", "Eδ"], ["1", "Bβ", "Cδ", "Dα", "Eγ", "Aε"], ["2", "Cγ", "Dε", "Eβ", "Aδ", "Bα"], ["3", "Dδ", "Eα", "Aγ", "Bε", "Cβ"], ["4", "Eε", "Aβ", "Bδ", "Cα", "Dγ"]],
               langkah=[("Huruf Latin: baris i, kolom j berisi (i + j) mod 5.", r"L^{(1)}_{2,3}=(2+3)\bmod5=0\ \Rightarrow\ A"),
                        ("Huruf Yunani: (i + 2j) mod 5.", r"L^{(2)}_{2,3}=(2+6)\bmod5=3\ \Rightarrow\ \delta"),
                        ("Periksa ortogonalitas: setiap pasangan huruf Latin–Yunani muncul tepat sekali di 25 sel.", r"5\times5=25\ \text{pasangan berbeda}"),
                        ("Acak urutan baris, kolom, dan pemetaan huruf ke perlakuan sebelum dipakai.", None)],
               simpul="Rancangan ini mengendalikan empat sumber keragaman dalam 25 percobaan dan menyisakan 8 db galat. Tabel di atas adalah bentuk standar; pengacakan baris, kolom, dan label tetap diperlukan."))

# ---------------------------------------------------------------- BIB / lattice
L("blok-tidak-lengkap-bib-lattice",
  [(r"Analisis dalam blok (intrablock)",
    [r"Karena tidak setiap perlakuan muncul di setiap blok, total perlakuan bercampur dengan efek blok tempat ia berada. Analisis dalam blok membersihkan efek blok dengan total terkoreksi \(Q_i\): total perlakuan dikurangi rata-rata total blok yang memuat perlakuan itu. JK perlakuan terkoreksi dihitung dari \(Q_i\), sedangkan JK blok dihitung biasa (tidak terkoreksi), dan galat adalah sisanya.",
     r"Rata-rata terkoreksi adalah rata-rata umum ditambah efek perlakuan terkoreksi. Semua selisih rata-rata terkoreksi punya galat baku yang sama, karena setiap pasangan muncul bersama sebanyak \(\lambda\) kali."],
    [r"Q_i=T_i-\frac{1}{k}\sum_{j\ni i}B_j,\qquad \hat{\tau}_i=\frac{kQ_i}{\lambda t},\qquad JKP_{\text{terkoreksi}}=\frac{k\sum_i Q_i^2}{\lambda t}",
     r"SE(\hat{\tau}_i-\hat{\tau}_{i'})=\sqrt{\frac{2k\,KTG}{\lambda t}}"]),
   (r"Pemulihan informasi antar blok",
    [r"Total blok juga membawa informasi tentang perlakuan, karena blok berbeda memuat perlakuan berbeda. Bila efek blok dianggap acak, informasi antar blok (interblock) dapat digabung dengan informasi dalam blok, dengan bobot kebalikan ragam masing-masing. Hasilnya penaksir yang lebih teliti, terutama bila keragaman antar blok tidak terlalu besar.",
     r"Saat ini penggabungan itu dilakukan otomatis oleh model campuran (REML) dengan blok sebagai efek acak."],
    [r"w=\frac{1}{\sigma^2},\qquad w'=\frac{1}{\sigma^2+k\sigma^2_\beta},\qquad \hat{\tau}^{*}_i\approx\frac{w\,E\,\hat{\tau}_i^{\text{intra}}+w'(1-E)\,\hat{\tau}_i^{\text{inter}}}{w\,E+w'(1-E)}"]),
   (r"Membangun rancangan BIB",
    [r"Ketaksamaan Fisher menyatakan bahwa BIB memerlukan sekurang-kurangnya sebanyak blok seperti perlakuan, \(b\ge t\). Cara sederhana membuat BIB: ambil semua kombinasi \(k\) dari \(t\) perlakuan (\(b=\binom{t}{k}\)), cocok untuk \(t\) kecil. Cara lain adalah konstruksi siklik: mulai dari satu blok awal, lalu tambahkan 1 modulo \(t\) berulang kali.",
     r"Bila BIB tidak tersedia untuk kombinasi \(t\) dan \(k\) yang diinginkan, gunakan rancangan blok tidak lengkap parsial (PBIB) atau rancangan alfa (alpha design) Patterson–Williams, yang menjadi pilihan baku pada uji galur dan varietas dengan banyak entri."],
    [r"rt=bk,\qquad \lambda(t-1)=r(k-1),\qquad b\ge t\ \ (\text{Fisher})"]),
   (r"Lattice dan rancangan alfa",
    [r"Lattice sederhana menempatkan \(t=k^2\) perlakuan dalam kisi \(k\times k\); ulangan pertama memakai baris kisi sebagai blok, ulangan kedua memakai kolom. Setiap ulangan lengkap (resolvable), sehingga bila efek blok kecil percobaan dapat dianalisis sebagai RAK. Lattice seimbang memakai \(k+1\) ulangan dan menjadi BIB.",
     r"Rancangan alfa memperumum gagasan ini untuk sembarang \(t=sk\) dan dipakai luas pada pemuliaan tanaman."],
    [])],
  [(r"Periksa apakah \(t=6\), \(k=3\), \(b=10\), \(r=5\) dapat menjadi BIB, dan cari \(\lambda\).",
    r"\(rt=30=bk\) terpenuhi. \(\lambda=r(k-1)/(t-1)=5(2)/5=2\), bilangan bulat, dan \(b=10\ge t=6\). Parameternya konsisten (BIB ini memang ada)."),
   (r"Hitung faktor efisiensi untuk \(t=7\), \(k=3\).",
    r"\(E=\frac{t(k-1)}{k(t-1)}=\frac{7(2)}{3(6)}=0{,}778\)."),
   (r"Pada BIB, mengapa JK blok dihitung tanpa koreksi, tetapi JK perlakuan harus dikoreksi?",
    r"Pada analisis dalam blok, blok dimasukkan ke model lebih dulu sehingga JK-nya apa adanya; perlakuan dimasukkan setelah blok sehingga JK-nya harus bersih dari efek blok (urutan JK sekuensial). Pada rancangan blok lengkap keduanya ortogonal sehingga urutan tidak berpengaruh."),
   (r"Berapa blok yang diperlukan bila BIB dibuat dari semua kombinasi 3 dari 5 perlakuan? Berapa \(r\) dan \(\lambda\)?",
    r"\(b=\binom{5}{3}=10\). \(r=bk/t=30/5=6\), \(\lambda=r(k-1)/(t-1)=6(2)/4=3\)."),
   (r"Uji 100 galur dengan blok berisi 10 petak. Rancangan apa yang sesuai?",
    r"Lattice 10×10 (\(t=k^2=100\)) atau rancangan alfa; setiap ulangan dibagi menjadi 10 blok tidak lengkap sehingga keragaman lahan dalam ulangan dapat dikendalikan.")],
  [R_MONT, R_CC, R_YATES, R_PW, R_KUEHL],
  contoh2=dict(judul="Contoh hitung kedua: analisis dalam blok untuk BIB",
               soal="Empat perlakuan diuji dalam BIB dengan t = 4, k = 3, b = 4, r = 3, λ = 2. Data per blok ada di tabel (tanda – berarti perlakuan tidak ada di blok itu).",
               data=[["Blok", "P1", "P2", "P3", "P4", "Total"], ["1", "12", "15", "16", "–", "43"], ["2", "11", "13", "–", "19", "43"], ["3", "10", "–", "15", "17", "42"], ["4", "–", "15", "16", "21", "52"], ["Total T_i", "33", "43", "47", "57", "180"]],
               langkah=[("Faktor koreksi, JK total (jumlah kuadrat data 2.812), dan JK blok.", r"FK=\frac{180^2}{12}=2700,\qquad JKT=112,\qquad JKB=\frac{43^2+43^2+42^2+52^2}{3}-FK=22"),
                        ("Total terkoreksi: total perlakuan dikurangi rata-rata total blok yang memuatnya.", r"Q_1=33-\frac{43+43+42}{3}=-9{,}67,\quad Q_2=-3{,}00,\quad Q_3=1{,}33,\quad Q_4=11{,}33"),
                        ("JK perlakuan terkoreksi.", r"JKP_{\text{terkoreksi}}=\frac{3\sum Q_i^2}{2\times4}=87{,}25"),
                        ("JK galat dengan db 11 − 3 − 3 = 5 dan uji F.", r"JKG=112-22-87{,}25=2{,}75,\quad KTG=0{,}55,\quad F=\frac{29{,}08}{0{,}55}=52{,}9\ (P=0{,}0003)"),
                        ("Rata-rata terkoreksi dan galat baku selisihnya.", r"\bar{y}^{\,adj}_i=15+\frac{3Q_i}{8}:\ 11{,}38;\ 13{,}88;\ 15{,}50;\ 19{,}25,\qquad SE=\sqrt{\frac{2(3)(0{,}55)}{8}}=0{,}64")],
               simpul="Perlakuan berbeda sangat nyata. Rata-rata terkoreksi (11,38; 13,88; 15,50; 19,25) berbeda dari rata-rata mentah (11,0; 14,3; 15,7; 19,0) karena P2 kebetulan sering berada di blok yang baik dan P1 di blok yang kurang baik."))

# ---------------------------------------------------------------- faktorial
L("percobaan-faktorial",
  [(r"Notasi efek pada faktorial 2^k",
    [r"Pada faktorial dua taraf, setiap kombinasi ditulis dengan huruf kecil faktor yang berada di taraf tinggi: (1), a, b, ab, dan seterusnya. Efek utama A adalah selisih rata-rata pada A tinggi dan A rendah; efek interaksi AB adalah separuh selisih efek A pada B tinggi dan B rendah. Semua efek dapat dihitung dari tabel tanda: kontras dibagi \(r2^{k-1}\), dan JK efek adalah kuadrat kontras dibagi \(r2^k\).",
     r"Algoritme Yates menghitung semua kontras sekaligus dengan penjumlahan dan pengurangan berpasangan yang diulang \(k\) kali, cara cepat yang dulu dipakai untuk hitung manual."],
    [r"A=\frac{1}{2r}\big[a+ab-b-(1)\big],\qquad AB=\frac{1}{2r}\big[ab+(1)-a-b\big],\qquad JK_{\text{efek}}=\frac{(\text{kontras})^2}{r\,2^k}"]),
   (r"Model tetap, acak, dan campuran",
    [r"Bila semua faktor tetap, setiap efek diuji dengan KTG. Bila sebagian faktor acak, penyebut uji F berubah menurut nilai harapan KT. Pada model campuran dengan A tetap dan B acak, efek utama A diuji dengan KT interaksi A×B, bukan KTG, karena keragaman interaksi ikut masuk ke nilai harapan KT A.",
     r"Contoh praktis: varietas (tetap) diuji di beberapa lokasi yang dipilih acak. Pengaruh varietas harus dibandingkan dengan seberapa tidak konsisten varietas itu antar lokasi (interaksi), bukan dengan galat dalam lokasi."],
    [r"A\ \text{tetap},\ B\ \text{acak}:\quad E(KTA)=\sigma^2+r\sigma^2_{AB}+\frac{rb\sum\alpha_i^2}{a-1},\qquad F_A=\frac{KTA}{KT_{AB}}"]),
   (r"Faktorial tanpa ulangan",
    [r"Faktorial \(2^k\) dengan \(k\) besar sering dijalankan tanpa ulangan, sehingga tidak ada db galat murni. Prinsip kejarangan efek (effect sparsity) menyatakan bahwa hanya sedikit efek yang benar-benar besar. Efek yang kecil diduga hanya galat; grafik normal atau setengah normal dari efek menunjukkan efek aktif sebagai titik yang menyimpang dari garis lurus.",
     r"Metode Lenth memberi uji formal: taksiran galat baku semu (PSE) dihitung dari median efek mutlak, lalu setiap efek dibagi PSE dan dibandingkan dengan sebaran t dengan \(m/3\) db, dengan \(m\) banyaknya efek."],
    [r"s_0=1{,}5\cdot\operatorname{median}|c_j|,\qquad PSE=1{,}5\cdot\operatorname{median}_{|c_j|<2{,}5s_0}|c_j|,\qquad t_j=\frac{c_j}{PSE}"]),
   (r"Faktor kuantitatif dan interaksi",
    [r"Bila salah satu faktor kuantitatif (misalnya dosis), JK faktor itu dan JK interaksinya dapat dipecah dengan kontras polinomial ortogonal. Komponen A × B linear menguji apakah kemiringan respon terhadap dosis berbeda antar taraf A; komponen A × B kuadratik menguji apakah kelengkungannya berbeda. Pemecahan ini jauh lebih informatif daripada notasi huruf untuk setiap kombinasi.",
     r"Hal yang sama dapat dilakukan dengan regresi: model respon terhadap dosis dengan kemiringan berbeda untuk setiap taraf A (ANCOVA dengan interaksi)."],
    [r"JK_{A\times B_{\text{lin}}}=\frac{\Big(\sum_i\sum_j c^{A}_i\,c^{\text{lin}}_j\,\bar{y}_{ij}\Big)^2}{\sum_i (c^{A}_i)^2\sum_j (c^{\text{lin}}_j)^2/r}"]),
   (r"Menyajikan dan menafsirkan interaksi",
    [r"Interaksi digambarkan dengan plot interaksi: rata-rata sel pada sumbu tegak, taraf satu faktor pada sumbu datar, dan garis untuk setiap taraf faktor lain. Garis sejajar berarti tidak ada interaksi; garis tidak sejajar berarti ada. Interaksi kuantitatif (arah sama, besar berbeda) masih memungkinkan pembahasan efek utama dengan hati-hati, sedangkan interaksi kualitatif (garis berpotongan, peringkat berbalik) mengharuskan pembahasan efek sederhana."],
    [])],
  [(r"Pada faktorial 2×2 dengan \(r=2\), total kombinasi (1) = 20, a = 30, b = 24, ab = 42. Hitung efek A, B, dan AB.",
    r"\(A=(30+42-24-20)/(2\times2)=28/4=7\). \(B=(24+42-30-20)/4=4\). \(AB=(42+20-30-24)/4=2\)."),
   (r"Dengan data yang sama, hitung JK A.",
    r"Kontras A \(=28\); \(JK_A=28^2/(2\times4)=784/8=98\)."),
   (r"Varietas (tetap) diuji di 5 lokasi yang dipilih acak. Dengan apa F varietas dihitung, dan mengapa?",
    r"F varietas \(=KT_V/KT_{V\times L}\), karena pada model campuran nilai harapan KT varietas memuat ragam interaksi varietas × lokasi. Kesimpulan lalu berlaku untuk populasi lokasi, bukan hanya lima lokasi itu."),
   (r"Faktorial \(2^4\) tanpa ulangan menghasilkan 15 efek. Efek-efek kecil dipakai Lenth. Berapa db sebaran t acuannya?",
    r"\(m/3=15/3=5\) db."),
   (r"Plot interaksi menunjukkan garis untuk dua varietas berpotongan: varietas 1 unggul pada dosis rendah, varietas 2 unggul pada dosis tinggi. Bagaimana menafsirkannya?",
    r"Interaksi kualitatif: tidak ada varietas yang terbaik secara umum. Bahas efek sederhana, yaitu perbandingan varietas pada setiap dosis, dan rekomendasikan varietas menurut dosis yang dipakai.")],
  [R_MONT, R_GOMEZ, R_MATT, R_BHH, R_LENTH],
  contoh2=dict(judul="Contoh hitung kedua: faktorial 2×3 dengan pemecahan polinomial",
               soal="Dua varietas (a1, a2) dan tiga dosis pupuk berjarak sama (b1, b2, b3) diuji dalam RAL dengan r = 3. Rata-rata sel (ton/ha) dan total ada di tabel; JK total 378.",
               data=[["Varietas", "b1", "b2", "b3", "Total"], ["a1", "21 (63)", "26 (78)", "29 (87)", "228"], ["a2", "23 (69)", "28 (84)", "35 (105)", "258"], ["Total", "132", "162", "192", "486"]],
               langkah=[("Faktor koreksi, JK A, JK B, dan JK kombinasi.", r"FK=\frac{486^2}{18}=13122,\quad JKA=\frac{228^2+258^2}{9}-FK=50,\quad JKB=\frac{132^2+162^2+192^2}{6}-FK=300"),
                        ("JK interaksi dan galat (JK kombinasi = 366, db galat 12).", r"JKAB=366-50-300=16,\qquad JKG=378-366=12,\qquad KTG=1{,}0"),
                        ("Uji F: A (db 1), B (db 2), A × B (db 2).", r"F_A=50,\quad F_B=150,\quad F_{AB}=8{,}0\ (P=0{,}006)"),
                        ("Pecah JK B dengan kontras linear (−1, 0, 1) dan kuadratik (1, −2, 1) pada rata-rata dosis 22, 27, 32.", r"JK_{B_{\text{lin}}}=\frac{(32-22)^2}{2/6}=300,\qquad JK_{B_{\text{kuad}}}=0"),
                        ("Pecah interaksi: kemiringan linear a1 = 29 − 21 = 8, a2 = 35 − 23 = 12.", r"JK_{A\times B_{\text{lin}}}=\frac{(12-8)^2}{4/3}=12,\qquad JK_{A\times B_{\text{kuad}}}=\frac{4^2}{12/3}=4")],
               simpul="Respon terhadap dosis linear (seluruh JK B bersifat linear). Interaksi nyata terutama karena kemiringan berbeda: hasil a2 naik 6 ton/ha per selang dosis, a1 hanya 4. Kedua varietas naik dengan dosis, tetapi a2 lebih responsif."))

# ---------------------------------------------------------------- faktorial pecahan
L("faktorial-pecahan-fractional-factorial",
  [(r"Membangun faktorial pecahan dari faktorial penuh dasar",
    [r"Faktorial \(2^{k-p}\) dibangun dengan menulis faktorial penuh untuk \(k-p\) faktor dasar, lalu mendefinisikan \(p\) faktor tambahan sebagai hasil kali kolom-kolom dasar. Setiap pembangkit menghasilkan satu kata dalam relasi pembangkit; relasi lengkap memuat semua pembangkit beserta hasil kali sesamanya (total \(2^p-1\) kata).",
     r"Alias suatu efek diperoleh dengan mengalikan efek itu dengan setiap kata dalam relasi pembangkit, memakai aturan bahwa kuadrat huruf apa pun sama dengan identitas."],
    [r"2^{6-2}:\ E=ABC,\ F=BCD\ \Rightarrow\ I=ABCE=BCDF=ADEF,\qquad A\cdot ABCE=BCE"]),
   (r"Pengaburan (confounding) untuk membagi blok",
    [r"Gagasan yang sama dipakai untuk menempatkan faktorial penuh ke dalam blok kecil. Pilih interaksi orde tinggi yang tidak penting, lalu tempatkan kombinasi bertanda + pada satu blok dan bertanda − pada blok lain. Interaksi itu tidak lagi dapat dibedakan dari efek blok (terkaburkan), tetapi semua efek lain tetap dapat ditaksir.",
     r"Pengaburan parsial mengaburkan interaksi yang berbeda di ulangan berbeda, sehingga setiap interaksi masih dapat ditaksir dari ulangan tempat ia tidak dikaburkan."],
    []),
   (r"Foldover untuk melepas alias",
    [r"Bila hasil rancangan resolusi III menunjukkan beberapa efek besar yang alias dengan interaksi dua faktor, jalankan fraksi kedua dengan semua tanda dibalik (foldover penuh). Gabungan kedua fraksi menjadi rancangan resolusi IV: efek utama bebas dari alias interaksi dua faktor. Foldover pada satu faktor saja membalik tanda faktor itu sehingga efek utamanya dan semua interaksi dua faktor yang melibatkannya terlepas.",
     r"Strategi berurutan seperti ini (screening, lalu klarifikasi) lebih hemat daripada langsung menjalankan rancangan besar."],
    []),
   (r"Rancangan Plackett–Burman dan aberasi minimum",
    [r"Plackett–Burman memberi rancangan penyaring (screening) dua taraf dengan \(N\) kelipatan 4 percobaan untuk sampai \(N-1\) faktor, misalnya 11 faktor dalam 12 percobaan. Rancangan ini resolusi III dengan pola alias yang kompleks: setiap interaksi dua faktor tersebar sebagian ke banyak efek utama.",
     r"Bila tersedia beberapa pecahan dengan resolusi sama, pilih yang beraberasi minimum: yang memiliki paling sedikit kata dengan panjang terpendek, sehingga paling sedikit interaksi orde rendah yang saling alias."],
    []),
   (r"Menganalisis pecahan tanpa ulangan",
    [r"Karena pecahan biasanya tidak diulang, analisis memakai grafik normal efek atau metode Lenth, ditambah prinsip hierarki efek: efek utama lebih mungkin besar daripada interaksi dua faktor, dan interaksi dua faktor lebih mungkin daripada interaksi orde tinggi. Prinsip heredity juga membantu menafsirkan alias: interaksi AB lebih mungkin aktif bila A atau B juga aktif."],
    [])],
  [(r"Untuk \(2^{5-1}\) dengan \(E=ABCD\), apa relasi pembangkit dan resolusinya?",
    r"\(I=ABCDE\), panjang kata 5, sehingga resolusi V: efek utama dan interaksi dua faktor tidak saling alias."),
   (r"Pada \(2^{6-2}\) dengan \(I=ABCE=BCDF=ADEF\), sebutkan alias efek A.",
    r"\(A\cdot ABCE=BCE\), \(A\cdot BCDF=ABCDF\), \(A\cdot ADEF=DEF\). Jadi A alias dengan BCE, DEF, dan ABCDF (semuanya interaksi orde tiga atau lebih)."),
   (r"Faktorial \(2^3\) dibagi ke dua blok dengan mengaburkan ABC. Kombinasi mana yang masuk blok yang sama dengan (1)?",
    r"Kombinasi dengan tanda ABC sama dengan (1), yaitu tanda −: (1), ab, ac, bc. Blok lain: a, b, c, abc."),
   (r"Rancangan resolusi III menunjukkan efek A dan B besar, padahal A alias dengan BC dan B alias dengan AC. Langkah apa untuk memastikan?",
    r"Jalankan foldover penuh (semua tanda dibalik). Gabungan kedua fraksi beresolusi IV sehingga A dan B terlepas dari interaksi dua faktor."),
   (r"Berapa faktor maksimum yang dapat disaring dengan Plackett–Burman 20 percobaan?",
    r"\(N-1=19\) faktor, dengan rancangan resolusi III.")],
  [R_MONT, R_BHH, R_WU, R_PB, R_LENTH],
  contoh2=dict(judul="Contoh hitung kedua: menaksir efek pada 2^{4−1}",
               soal="Pecahan 2^{4−1} dengan D = ABC dijalankan dengan urutan standar A, B, C. Respon (rendemen, %) tercatat di tabel. Taksir efek dan tafsirkan aliasnya.",
               data=[["Run", "A", "B", "C", "D = ABC", "y"], ["1", "−", "−", "−", "−", "50"], ["2", "+", "−", "−", "+", "64"], ["3", "−", "+", "−", "+", "52"], ["4", "+", "+", "−", "−", "70"], ["5", "−", "−", "+", "+", "55"], ["6", "+", "−", "+", "−", "69"], ["7", "−", "+", "+", "−", "58"], ["8", "+", "+", "+", "+", "82"]],
               langkah=[("Relasi pembangkit dan struktur alias (resolusi IV).", r"I=ABCD:\quad A=BCD,\ B=ACD,\ C=ABD,\ D=ABC,\ AB=CD,\ AC=BD,\ AD=BC"),
                        ("Efek = kontras dibagi N/2 = 4. Efek A:", r"A=\frac{(64+70+69+82)-(50+52+55+58)}{4}=\frac{285-215}{4}=17{,}5"),
                        ("Efek lainnya dengan cara yang sama.", r"B=6{,}0,\quad C=7{,}0,\quad D=1{,}5,\quad AB+CD=3{,}5,\quad AC+BD=1{,}5,\quad AD+BC=2{,}0"),
                        ("Urutkan efek mutlak dan nilai dengan grafik normal: A menonjol, B dan C sedang, sisanya kecil.", None)],
               simpul="Faktor A paling berpengaruh (+17,5), diikuti C (+7) dan B (+6); D hampir tidak berpengaruh. Efek 3,5 milik AB atau CD; dengan prinsip heredity, AB lebih mungkin karena A dan B aktif sedangkan D tidak."))

# ---------------------------------------------------------------- split-plot
L("petak-terbagi-split-plot",
  [(r"Nilai harapan kuadrat tengah dan dua galat",
    [r"Petak utama adalah satuan percobaan bagi faktor A; anak petak adalah satuan percobaan bagi faktor B. Karena itu ada dua galat: galat (a) adalah interaksi kelompok × A dan menggambarkan keragaman antar petak utama, sedangkan galat (b) menggambarkan keragaman antar anak petak dalam petak utama. Nilai harapan KT menunjukkan pasangan uji yang tepat.",
     r"Umumnya galat (a) lebih besar daripada galat (b), karena petak utama lebih besar dan lebih beragam. Akibatnya efek A diuji dengan db sedikit dan galat besar, sehingga kuasanya rendah; inilah harga yang dibayar untuk kemudahan menerapkan A pada petak besar."],
    [r"E(KT_{\text{galat a}})=\sigma^2_b+b\,\sigma^2_a,\qquad E(KTA)=\sigma^2_b+b\,\sigma^2_a+\frac{rb\sum\alpha_i^2}{a-1},\qquad E(KT_{\text{galat b}})=\sigma^2_b"]),
   (r"Galat baku empat jenis perbandingan",
    [r"Galat baku selisih bergantung pada jenis perbandingannya. Dua perbandingan pertama memakai satu galat saja. Perbandingan dua taraf A pada taraf B yang sama (atau berbeda) melibatkan kedua galat, sehingga galat bakunya adalah gabungan, dan nilai t kritisnya juga gabungan berbobot (pendekatan Cochran–Cox) atau memakai derajat bebas Satterthwaite."],
    [r"\bar{y}_{i\cdot}-\bar{y}_{i'\cdot}:\ \sqrt{\frac{2E_a}{rb}},\qquad \bar{y}_{\cdot j}-\bar{y}_{\cdot j'}:\ \sqrt{\frac{2E_b}{ra}},\qquad \bar{y}_{ij}-\bar{y}_{ij'}:\ \sqrt{\frac{2E_b}{r}}",
     r"\bar{y}_{ij}-\bar{y}_{i'j}:\ \sqrt{\frac{2\big[(b-1)E_b+E_a\big]}{rb}},\qquad t'=\frac{(b-1)E_b\,t_b+E_a\,t_a}{(b-1)E_b+E_a}"]),
   (r"Derajat bebas Satterthwaite",
    [r"Galat baku gabungan adalah kombinasi linear dua kuadrat tengah, sehingga tidak menyebar persis khi-kuadrat. Satterthwaite memberi derajat bebas efektif untuk kombinasi seperti itu. Metode ini juga dipakai secara otomatis oleh model campuran (pendekatan Kenward–Roger atau Satterthwaite) untuk data tidak seimbang."],
    [r"\nu=\frac{\big[(b-1)E_b+E_a\big]^2}{\dfrac{\big[(b-1)E_b\big]^2}{db_b}+\dfrac{E_a^2}{db_a}}"]),
   (r"Split-plot dalam waktu dan model campuran",
    [r"Pengukuran berulang pada petak yang sama (misalnya hasil panen tahun 1, 2, 3) sering dianalisis sebagai split-plot dalam waktu, dengan waktu sebagai anak petak. Analisis ini mengandaikan korelasi antar waktu sama (sphericity); bila tidak, gunakan pengukuran berulang dengan koreksi atau model campuran dengan struktur kovarians yang sesuai.",
     r"Model campuran dengan efek acak kelompok dan kelompok × A memberi hasil yang sama untuk data seimbang, dan tetap sah untuk data tidak seimbang atau hilang."],
    [r"y_{kij}=\mu+\rho_k+\alpha_i+(\rho\alpha)_{ki}+\beta_j+(\alpha\beta)_{ij}+\varepsilon_{kij},\qquad (\rho\alpha)_{ki}\sim N(0,\sigma^2_a),\ \varepsilon_{kij}\sim N(0,\sigma^2_b)"]),
   (r"Kapan memilih split-plot",
    [r"Pilih split-plot bila satu faktor memerlukan petak besar atau sulit diubah (pengolahan tanah, irigasi, suhu ruang tumbuh, tanggal tanam), atau bila faktor tambahan ingin disisipkan pada percobaan yang sudah berjalan. Tempatkan faktor yang paling ingin diteliti secara teliti, dan interaksinya, pada anak petak."],
    [])],
  [(r"Mengapa faktor petak utama pada split-plot sering tidak nyata walaupun selisih rata-ratanya besar?",
    r"Karena diuji dengan galat (a) yang biasanya besar dan derajat bebasnya sedikit \((r-1)(a-1)\). Nilai kritis F menjadi tinggi dan kuasanya rendah."),
   (r"Split-plot dengan \(a=3\), \(b=4\), \(r=4\). Hitung db galat (a), db galat (b), dan db total.",
    r"Galat (a): \((4-1)(3-1)=6\). Galat (b): \(3(4-1)(4-1)=27\). Total: \(48-1=47\)."),
   (r"\(E_a=12\), \(E_b=3\), \(r=3\), \(b=4\). Hitung galat baku selisih dua rata-rata A, dan dua rata-rata B pada A yang sama.",
    r"Rata-rata A: \(\sqrt{2(12)/12}=1{,}41\). B pada A sama: \(\sqrt{2(3)/3}=1{,}41\). Kebetulan sama di sini; umumnya keduanya berbeda."),
   (r"Dengan data soal sebelumnya, hitung galat baku selisih dua taraf A pada taraf B yang sama.",
    r"\(\sqrt{2[(4-1)3+12]/(3\times4)}=\sqrt{2(21)/12}=\sqrt{3{,}5}=1{,}87\)."),
   (r"Faktor irigasi (sulit diubah) dan varietas (mudah) diteliti bersama. Faktor mana yang ditempatkan di petak utama?",
    r"Irigasi di petak utama karena memerlukan petak besar; varietas di anak petak sehingga efek varietas dan interaksi irigasi × varietas diuji lebih teliti.")],
  [R_GOMEZ, R_MONT, R_MATT, R_MJ, R_SATT, R_SASMIX],
  contoh2=dict(judul="Contoh hitung kedua: sidik ragam split-plot lengkap",
               soal="Dua cara olah tanah (T1, T2) sebagai petak utama dan tiga varietas (V1–V3) sebagai anak petak, dalam tiga kelompok. Hasil (kuintal/ha) ada di tabel; JK total 390,44.",
               data=[["Kelompok", "T1V1", "T1V2", "T1V3", "T2V1", "T2V2", "T2V3"], ["1", "30", "34", "37", "33", "38", "43"], ["2", "26", "31", "33", "35", "37", "43"], ["3", "31", "37", "38", "31", "38", "43"], ["Rata-rata", "29,0", "34,0", "36,0", "33,0", "37,7", "43,0"]],
               langkah=[("Analisis petak utama dari total kelompok × T (101, 114; 90, 115; 106, 112).", r"FK=\frac{638^2}{18}=22613{,}56,\quad JKK=15{,}44,\quad JK_{\text{olah}}=107{,}56,\quad JK_{\text{galat a}}=30{,}78"),
                        ("KT galat (a) dengan db 2 dan uji F olah tanah.", r"E_a=15{,}39,\qquad F_T=\frac{107{,}56}{15{,}39}=6{,}99\ (P=0{,}118),\quad F_{0{,}05;1,2}=18{,}51"),
                        ("Analisis anak petak.", r"JKV=218{,}11,\quad JK_{T\times V}=10{,}11,\quad JK_{\text{galat b}}=8{,}44,\quad E_b=1{,}056\ (db\ 8)"),
                        ("Uji F varietas dan interaksi dengan db penyebut 8.", r"F_V=103{,}3\ (P<0{,}001),\qquad F_{T\times V}=4{,}79\ (P=0{,}043)"),
                        ("Galat baku perbandingan dua cara olah pada varietas sama, dengan t gabungan.", r"SE=\sqrt{\frac{2[2(1{,}056)+15{,}39]}{9}}=1{,}97,\qquad t'=\frac{2(1{,}056)(2{,}306)+15{,}39(4{,}303)}{2(1{,}056)+15{,}39}=4{,}06")],
               simpul="Varietas dan interaksi nyata, tetapi olah tanah tidak nyata (P = 0,118) walaupun selisih rata-ratanya 4,9 kuintal, karena galat (a) besar (KK 11,1%) dengan hanya 2 db. Batas beda nyata dua cara olah pada varietas yang sama adalah t′ × SE = 4,06 × 1,97 = 8,0; selisih terbesar (pada V3, 43,0 − 36,0 = 7,0) pun belum melewatinya. Untuk menguji olah tanah dengan baik, percobaan perlu lebih banyak kelompok."))

# ---------------------------------------------------------------- split-split-plot
L("petak-terbagi-dua-kali-split-split-plot",
  [(r"Model dan nilai harapan",
    [r"Split-split-plot memiliki tiga satuan percobaan bersarang: petak utama (faktor A), anak petak (faktor B), dan anak-anak petak (faktor C). Setiap tingkat punya galatnya sendiri, dan setiap efek diuji dengan galat dari tingkat satuan tempat efek itu berada: A dengan galat (a); B dan A × B dengan galat (b); C dan semua interaksi yang memuat C dengan galat (c).",
     r"Nilai harapan KT menunjukkan susunan itu: galat (a) memuat ketiga komponen ragam, galat (b) memuat dua, galat (c) hanya satu."],
    [r"E(E_a)=\sigma^2_c+c\sigma^2_b+bc\sigma^2_a,\qquad E(E_b)=\sigma^2_c+c\sigma^2_b,\qquad E(E_c)=\sigma^2_c"]),
   (r"Galat baku perbandingan",
    [r"Seperti split-plot, galat baku bergantung pada jenis perbandingan. Perbandingan yang hanya melibatkan satu tingkat memakai satu galat; perbandingan lintas tingkat (misalnya dua taraf A pada kombinasi B dan C yang sama) memakai gabungan galat dengan t' berbobot atau derajat bebas Satterthwaite."],
    [r"\bar{y}_{i\cdot\cdot}:\ \sqrt{\frac{2E_a}{rbc}},\quad \bar{y}_{\cdot j\cdot}:\ \sqrt{\frac{2E_b}{rac}},\quad \bar{y}_{\cdot\cdot k}:\ \sqrt{\frac{2E_c}{rab}},\quad \bar{y}_{ijk}-\bar{y}_{ijk'}:\ \sqrt{\frac{2E_c}{r}}"]),
   (r"Menafsirkan interaksi tiga faktor",
    [r"Interaksi A × B × C berarti interaksi dua faktor (misalnya B × C) berbeda menurut taraf faktor ketiga. Cara menafsirkannya: pecah menurut taraf satu faktor dan buat plot interaksi dua faktor untuk setiap taraf itu. Bila interaksi tiga faktor tidak nyata, bahas interaksi dua faktor yang nyata; bila tidak ada yang nyata, bahas efek utama.",
     r"Dengan tiga galat dan banyak sumber keragaman, risiko menemukan efek palsu cukup besar. Batasi pembahasan pada efek yang bermakna secara agronomi atau teknis, bukan hanya yang nyata secara statistik."],
    []),
   (r"Alternatif yang lebih sederhana",
    [r"Rancangan ini rumit dalam pelaksanaan dan analisis. Bila memungkinkan, pertimbangkan split-plot dengan faktorial B × C di anak petak (hanya dua galat), atau strip-split-plot bila dua faktor perlu jalur. Untuk data tidak seimbang, model campuran dengan efek acak kelompok, kelompok × A, dan kelompok × A × B adalah cara yang paling aman."],
    [r"y=\mu+\rho_k+\alpha_i+(\rho\alpha)_{ki}+\beta_j+(\alpha\beta)_{ij}+(\rho\alpha\beta)_{kij}+\gamma_l+(\alpha\gamma)+(\beta\gamma)+(\alpha\beta\gamma)+\varepsilon"])],
  [(r"Split-split-plot dengan \(a=3\), \(b=2\), \(c=4\), \(r=3\). Hitung db galat (a), (b), dan (c).",
    r"Galat (a): \((r-1)(a-1)=4\). Galat (b): \(a(r-1)(b-1)=6\). Galat (c): \(ab(r-1)(c-1)=3(2)(2)(3)=36\)."),
   (r"Dengan galat apa interaksi A × C diuji, dan mengapa?",
    r"Dengan galat (c), karena interaksi yang memuat C berada di tingkat anak-anak petak, satuan percobaan tempat C diterapkan."),
   (r"\(E_c=4\), \(r=3\), \(a=2\), \(b=3\). Hitung galat baku selisih dua rata-rata C (dirata-ratakan atas A dan B).",
    r"\(\sqrt{2(4)/(3\times2\times3)}=\sqrt{8/18}=0{,}67\)."),
   (r"Bagaimana menafsirkan interaksi A × B × C yang nyata?",
    r"Interaksi dua faktor berbeda menurut taraf faktor ketiga. Buat plot interaksi B × C untuk setiap taraf A dan bahas pola di masing-masing taraf."),
   (r"Kapan sebaiknya memilih split-plot dengan faktorial B × C di anak petak daripada split-split-plot?",
    r"Bila B dan C sama mudah diterapkan pada satuan kecil. Rancangan itu hanya punya dua galat, lebih sederhana, dan B mendapat ketelitian yang sama dengan C.")],
  [R_GOMEZ, R_MATT, R_MJ, R_SASMIX],
  contoh2=dict(judul="Contoh kedua: galat baku berbagai perbandingan",
               soal="Split-split-plot dengan a = 2 (irigasi), b = 3 (varietas), c = 2 (dosis N), r = 3 kelompok memberi E_a = 12, E_b = 6, E_c = 4. Hitung galat baku selisih untuk berbagai perbandingan.",
               data=[["Perbandingan", "Rumus", "SE"], ["Dua rata-rata A", "√(2E_a/rbc)", "1,15"], ["Dua rata-rata B", "√(2E_b/rac)", "1,00"], ["Dua rata-rata C", "√(2E_c/rab)", "0,67"], ["Dua B pada A sama", "√(2E_b/rc)", "1,41"], ["Dua C pada A sama", "√(2E_c/rb)", "0,94"], ["Dua C pada A dan B sama", "√(2E_c/r)", "1,63"]],
               langkah=[("Derajat bebas ketiga galat.", r"db_a=(3-1)(2-1)=2,\quad db_b=2(2)(2)=8,\quad db_c=6(2)(1)=12"),
                        ("Rata-rata A dirata-ratakan atas r × b × c = 18 pengamatan.", r"SE=\sqrt{\frac{2(12)}{18}}=1{,}15"),
                        ("Rata-rata C di dalam satu kombinasi A dan B hanya memuat r = 3 pengamatan.", r"SE=\sqrt{\frac{2(4)}{3}}=1{,}63")],
               simpul="Walaupun E_c terkecil, perbandingan C di dalam satu kombinasi A dan B punya galat baku terbesar karena hanya memakai 3 pengamatan per rata-rata. Galat baku selalu bergantung pada galat yang dipakai sekaligus pada banyaknya pengamatan di balik rata-rata."))
